"""NS7III owner-probed normal EQ addresses without motor or sibling inference."""
from curated import add, profile

NS7III_EQ_REFERENCES={"Numark NS7 III":{'url': 'https://raw.githubusercontent.com/djcmd-project/djcmd/0f8830a2d886450e81e07cd7b957d6ebe4a4856f/ns7iii_map.h', 'sha256': '15d944b8d9475243715907ee2d1219744f32325b55c9ee4d974f6918ab75d880', 'upstreamRevision': '0f8830a2d886450e81e07cd7b957d6ebe4a4856f', 'files': [{'cachePath': 'TestBuilds/r464/upstream/ns7iii_map.h', 'sha256': '15d944b8d9475243715907ee2d1219744f32325b55c9ee4d974f6918ab75d880'}, {'cachePath': 'TestBuilds/r464/upstream/README.md', 'sha256': 'e909abd48a4fcd37e6ce967960723525f6ba981fd3f5dc1283dfdad2c140c37f'}, {'cachePath': 'TestBuilds/r464/upstream/djcmd_midi.c', 'sha256': '5d9e667ffa4773a72fc86c368154d38758d0ae65502c86706071a419a3defa7d'}, {'cachePath': 'TestBuilds/r464/upstream/ns7iii-manual.pdf', 'sha256': 'e3572ff8bae54d8e14005ebb72b8ed8e018749ed824f44f81999277504473cf8'}], 'relatedSources': [{'url': 'https://raw.githubusercontent.com/djcmd-project/djcmd/0f8830a2d886450e81e07cd7b957d6ebe4a4856f/README.md'}, {'url': 'https://raw.githubusercontent.com/djcmd-project/djcmd/0f8830a2d886450e81e07cd7b957d6ebe4a4856f/djcmd_midi.c'}, {'url': 'https://www.numark.com/images/product_downloads/NS7IIIUserGuide-v1.1.pdf', 'sha256': 'e3572ff8bae54d8e14005ebb72b8ed8e018749ed824f44f81999277504473cf8'}], 'review': 'Pinned primary owner project djcmd at0f8830a2d886450e81e07cd7b957d6ebe4a4856f. Its map explicitly labels twelve EQ CC numbers as probed from hardware and identifies strip order3/1/2/4. Native transcribes only those raw0 addresses: CH1 low9/mid10/high11, CH2 low14/mid15/high16, CH3 low20/mid21/high22 and CH4 low25/mid26/high27, assigning logical CH1..4 to A..D. The actual map rows and own decoder independently establish normal absolute EQ roles and increasing value direction. This is a manual7-bit coarse subset of the reported high-byte wires. The decoder has14-bit EQ paths but this map does not qualify the EQ low-byte addresses; no plus32 guess or14-bit claim is made. C/D require app opt-in and all knobs retain source-owned pickup. The owner labels other values unconfirmed by capture; none are used. The project is AI-assisted; its explicit hardware-probe statement is community evidence, not a manufacturer wire specification or native hardware test. Numark own v1.1 guide independently establishes normal EQ roles, PC-only MIDI source and Touch/TouchLock EQ-kill behaviour. Select PC and keep native normal EQ use separate from those unimplemented modes. Requires an already exposed CoreMIDI source or a separately qualified bridge. Direct iPad USB/driver, complete source/layer/Touch state, higher resolution, transport, pads, motors/platter calibration, screens/feedback, lifecycle/recovery, OS/power/audio/DVS and physical/iPad/A10X acceptance remain open. No upstream code/map is bundled or executed; only these factual assignments are transcribed. No motor, heartbeat, init, firmware, driver, query, preset, touch, lamp, screen or audio-route packet is sent. NS7/NS7II bytes and identities are not inherited.'}}


def ns7iii_eq_profiles():
    """Return only the reported coarse EQ wires through a manual exposed MIDI port."""
    ref=NS7III_EQ_REFERENCES['Numark NS7 III']
    p=profile('Numark NS7 III',ref['url'])
    p.update(autoSelect=False,role='accessory',definition='reviewed:ns7iii-owner-probed-coarse-eq',
        aliases=['Numark NS7 III','Numark NS7III','NS7III','NS7 III'],
        excludedAliases=['NS7','NS7II','NS7 II','Numark NS7','Numark NS7II'],
        hardwareMode='Manual exposed CoreMIDI source only; direct iPad USB/driver and bridge qualification remain open. Set channel Input Selectors to PC and use normal software EQ with Touch/TouchLock inactive. Physical CH1..4 map A..D; C/D require app opt-in. Configure app audio separately.',
        scope='Manual twelve-knob coarse normal EQ subset from owner-reported hardware probes. Seven-bit high-byte controls only, with source-owned pickup. Complete resolution, controls/modes, motors/screens/lifecycle/audio and theoretical/physical acceptance remain open.',
        gaps=[ref['review']])
    for deck,base in zip('abcd',[9,14,20,25]):
        for offset,action in enumerate(['low','mid','high']):add(p,action,0,base+offset,'control',deck=deck)
    return [p]
